typedef struct {
    const int16_t *pcm;
    uint32_t samples;
} ban_sfx_clip_t;

static const ban_sfx_clip_t s_clips[BAN_SFX_COUNT] = {
    { s_click, (uint32_t)(sizeof(s_click) / sizeof(s_click[0])) },
    { s_warning, (uint32_t)(sizeof(s_warning) / sizeof(s_warning[0])) },
    { s_scan, (uint32_t)(sizeof(s_scan) / sizeof(s_scan[0])) },
    { s_ban, (uint32_t)(sizeof(s_ban) / sizeof(s_ban[0])) },
    { s_reject, (uint32_t)(sizeof(s_reject) / sizeof(s_reject[0])) },
};

const int16_t *ban_sfx_pcm(ban_sfx_id_t id, uint32_t *samples) {
    if ((unsigned)id >= BAN_SFX_COUNT) {
        if (samples) *samples = 0;
        return NULL;
    }
    if (samples) *samples = s_clips[id].samples;
    return s_clips[id].pcm;
}
